const save = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!value || disabled || actionLock.current) return
    actionLock.current = true
    setSaving(true)
    setActionError(null)
    try {
      if (await store.setCredential(provider, kind, value)) setValue('')
      else setActionError('Could not confirm saving this credential. Check its status before retrying.')
    } finally {
      actionLock.current = false
      setSaving(false)
    }
  }

async setCredential(provider: string, kind: string, value: string): Promise<boolean> {
    if (this.snapshot.scope.kind === 'remote') return false
    if (!value) return false
    const result = await this.act('Could not save provider credential', () => this.context.call('quirky.accounts/setCredential', { provider, kind, value }))
    if (result === null) return false
    const status = parseCredentialStatus(result)
    if (status) this.updateCredential(status)
    else void this.loadCredentials()
    await this.refresh(provider)
    return true
  }

const clear = async () => {
    if (disabled || actionLock.current) return
    actionLock.current = true
    setClearing(true)
    setActionError(null)
    try {
      if (!await store.clearCredential(provider, kind)) setActionError('Could not confirm clearing this credential. Check its status before retrying.')
    } finally {
      actionLock.current = false
      setClearing(false)
    }
  }

async clearCredential(provider: string, kind: string): Promise<boolean> {
    if (this.snapshot.scope.kind === 'remote') return false
    const result = await this.act('Could not clear provider credential', () => this.context.call('quirky.accounts/clearCredential', { provider, kind }))
    if (result === null) return false
    const status = parseCredentialStatus(result)
    if (status) this.updateCredential(status)
    else void this.loadCredentials()
    await this.refresh(provider)
    return true
  }

const update = async (value: boolean) => {
    setSaving(true)
    try {
      await context.call('setting.set', { id: GEMINI_CLI_OAUTH_SETTING_ID, value })
      setEnabled(value)
    } catch {
      context.toast('Could not update Gemini CLI access', 'The setting could not be saved.')
    } finally {
      setSaving(false)
    }
  }

